package fast.tv

class Player(private val api: PlatformApi, private val video: VideoSurface) {
    // Pressing play asks the gateway for a manifest, then streams it.
    suspend fun play(episodeId: String) {
        val playback = api.get<PlaybackResponse>("/api/play/$episodeId")
        video.load(playback.manifest, playback.licence)
        video.start()
    }
}

