// The web app's calls into the platform. Every request goes through the
// API gateway; the app never talks to a service directly.
import { session } from "./session";

const BASE = "/api";

export async function search(query: string) {
  const response = await fetch(`${BASE}/search?q=${encodeURIComponent(query)}`, {
    headers: { authorization: session.token() },
  });

  return (await response.json()) as SearchResult[];
}

export async function title(id: string) {
  const response = await fetch(`${BASE}/titles/${id}`);
  return response.json();
}

