resource "aws_s3_bucket" "segments" {
  bucket = "video-segments"
}

resource "aws_s3_bucket_lifecycle_configuration" "segments" {
  bucket = aws_s3_bucket.segments.id
  rule {
    id     = "expire-drafts"
    status = "Enabled"
    filter { prefix = "drafts/" }
    expiration { days = 7 }
  }
}

# A new manifest in the bucket announces the title on Events.
resource "aws_s3_bucket_notification" "ready" {
  bucket = aws_s3_bucket.segments.id
  queue {
    queue_arn     = aws_msk_bridge.events.arn
    events        = ["s3:ObjectCreated:*"]
    filter_suffix = "manifest.m3u8"
  }
}

