package gateway

import (
	"net/http"

	"golang.org/x/sync/errgroup"
)

func (s *Server) Routes(mux *http.ServeMux) {
	mux.HandleFunc("GET /api/play/{id}", s.play)
	mux.HandleFunc("GET /api/search", s.search)
}

// play asks Playback for a manifest and Catalog for the title at once.
func (s *Server) play(w http.ResponseWriter, r *http.Request) {
	id := r.PathValue("id")
	g, ctx := errgroup.WithContext(r.Context())

	var manifest playback.Manifest
	var title catalog.Title
	g.Go(func() (err error) { manifest, err = s.playback.Manifest(ctx, id); return })
	g.Go(func() (err error) { title, err = s.catalog.Title(ctx, id); return })

	if err := g.Wait(); err != nil {
		writeError(w, err)
		return
	}
	writeJSON(w, PlayResponse{Manifest: manifest, Title: title})
}

func (s *Server) search(w http.ResponseWriter, r *http.Request) {
	results, err := s.catalog.Search(r.Context(), r.URL.Query().Get("q"))
	if err != nil {
		writeError(w, err)
		return
	}
	writeJSON(w, results)
}

