import { elastic } from "./elastic";

// Full-text search over titles, ranked for the viewer by Search.
export async function searchTitles(query: string, viewer: string) {
  const result = await elastic.search({
    index: "titles",
    query: { multi_match: { query, fields: ["name^3", "synopsis", "cast"] } },
    rank: { viewer },
  });

  return result.hits.hits.map((hit) => hit._source);
}

