package drm

// Licence issues a playback licence when the viewer's plan covers the title.
func (s *Service) Licence(ctx context.Context, viewer, episode string) (Licence, error) {
	var plan string
	err := s.db.QueryRow(ctx, `SELECT plan FROM accounts WHERE id = $1`, viewer).Scan(&plan)
	if err != nil {
		return Licence{}, err
	}
	if !covers(plan, episode) {
		return Licence{}, ErrNotCovered
	}
	return s.sign(viewer, episode, plan), nil
}

