package playback

// Manifest returns the stream manifest for an episode, but only once DRM
// has issued a licence for this viewer.
func (s *Service) Manifest(ctx context.Context, episode string) (Manifest, error) {
	viewer := auth.Viewer(ctx)

	licence, err := s.drm.Licence(ctx, viewer, episode)
	if err != nil {
		return Manifest{}, fmt.Errorf("licence: %w", err)
	}

	return s.manifests.For(episode, licence), nil
}

