package rank

// The ranking plugin boosts titles close to what the viewer watched lately.
func (p *Plugin) Boosts(ctx context.Context, viewer string) (map[string]float64, error) {
	recent, err := p.redis.LRange(ctx, "recent:"+viewer, 0, 49).Result()
	if err != nil {
		return nil, err
	}
	return similarTo(recent), nil
}

