package transcoder

var renditions = []Rendition{R720p, R1080p, R4K}

// Run transcodes an upload into every rendition and stores the segments.
func (j *Job) Run(ctx context.Context, upload Upload) error {
	for _, r := range renditions {
		segments, err := ffmpeg.Segment(ctx, upload.Path, r)
		if err != nil {
			return err
		}
		for _, seg := range segments {
			if _, err := j.s3.PutObject(ctx, &s3.PutObjectInput{
				Bucket: aws.String("video-segments"),
				Key:    aws.String(seg.Key(upload.Title, r)),
				Body:   seg.Body,
			}); err != nil {
				return err
			}
		}
	}
	return nil
}
